add_filter( 'woocommerce_default_address_fields', 'perfectpixel_address_field_dropdown', 9999 );

function perfectpixel_address_field_dropdown( $fields ) {
	$field = 'address_2';

	// Value => label. The first entry is the "please choose" option.
	$options = array(
		''        => 'Επιλέξτε…',
		'ground'  => 'Ισόγειο',
		'floor-1' => '1ος όροφος',
		'floor-2' => '2ος όροφος',
		'floor-3' => '3ος όροφος και πάνω',
	);

	if ( isset( $fields[ $field ] ) ) {
		$fields[ $field ]['type']        = 'select';
		$fields[ $field ]['options']     = $options;
		unset( $fields[ $field ]['placeholder'] );
	}

	return $fields;
}
